function anchors(){if(!target)return[];const selectors=['.cs-pageheading','.cs-explain','.cs-depth>section','.pl-lab','.cs-quiz','.cs-evidence','.cs-source','.cs-note','.cs-organizer'];const list=[...target.querySelectorAll(selectors.join(','))];return list.length?list:[target];}
