function scheduleDraw(){if(!frame)frame=requestAnimationFrame(draw);}
function dist(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=dx||dy?Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy))):0;return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);}
function erase(ev){const r=target.getBoundingClientRect(),p={x:ev.clientX-r.left,y:ev.clientY-r.top},before=pages[pageKey]||[];const after=before.filter(stroke=>{const ps=absolute(stroke);if(ps.length===1)return Math.hypot(ps[0].x-p.x,ps[0].y-p.y)>16;return !ps.some((b,i)=>i&&dist(p,ps[i-1],b)<=16);});if(after.length!==before.length){pages[pageKey]=after;scheduleDraw();persist();}}
