function move(ev){if(pointer!==ev.pointerId)return;ev.preventDefault();if(mode==='eraser'){erase(ev);return;}if(!active)return;const samples=ev.getCoalescedEvents?.()||[ev];for(const e of samples.length?samples:[ev]){const p=point(e,rectFor(active)),last=active.points.at(-1);if(Math.hypot(p.x-last.x,p.y-last.y)>.0005)active.points.push(p);}scheduleDraw();}
