function keyFor(){if(isLibrary()){const ch=document.querySelector('#cs-chapter'),p=document.querySelector('#cs-page');if(!ch||!p)return null;const course=location.hash.split('/')[2];return `course:${course}:${ch.value}:${p.value}`;}const match=location.hash.match(/^#(w\d+)\/(\d+)\/(\w+)/);return match?`unix:${match[1]}:${match[2]}:${match[3]}`:null;}
function refresh(){applySide();const nextKey=keyFor(),next=nextKey?(isLibrary()?document.querySelector('.cs-lesson'):document.querySelector('#panel')):null;if(next===target&&nextKey===pageKey&&svg?.isConnected){scheduleDraw();return;}finish();resize?.disconnect();svg?.remove();target?.classList.remove('notebook-paper');target=next;pageKey=nextKey||'';svg=null;tools.querySelectorAll('[data-ink-mode]').forEach(b=>b.disabled=!target);if(!target){setMode('move');return;}target.classList.add('notebook-paper');svg=document.createElementNS(NS,'svg');svg.id='notebook-ink';svg.setAttribute('aria-label','이 페이지의 필기 레이어');svg.setAttribute('role','img');svg.addEventListener('pointerdown',down);svg.addEventListener('pointermove',move);svg.addEventListener('pointerup',finish);svg.addEventListener('pointercancel',finish);svg.addEventListener('lostpointercapture',()=>{if(pointer!==null){pointer=null;if(active){active=null;persist();}}});target.append(svg);resize=new ResizeObserver(scheduleDraw);resize.observe(target);anchors().forEach(a=>resize.observe(a));setMode(mode);scheduleDraw();}
